VALUES
('b1b3bb20-5975-47bb-83d9-8c15c1f8d6c0', 'Khảo sát trải nghiệm website', 'Khảo sát này nhằm thu thập ý kiến của người dùng về trải nghiệm sử dụng website của chúng tôi.', 'PUBLIC', '7c64445b-8803-4de4-ac2e-8c34d83db6bb', NOW(), NOW()),
('1d07f26b-dede-4a79-ba5a-bfc4d883001f', 'Ý kiến về tính năng mới', 'Khảo sát này thu thập ý tưởng và đề xuất của bạn về các tính năng mới mà bạn mong muốn được phát triển.', 'PUBLIC', '59341852-06eb-4a91-a06a-e46e321fddbf', NOW(), NOW()),
('1e69cc3d-1d10-43ea-9226-2dc6ebd8a2b1', 'Đánh giá mức độ hài lòng của khách hàng', 'Giúp chúng tôi hiểu mức độ hài lòng của bạn đối với dịch vụ và sản phẩm hiện tại.', 'PUBLIC', 'a1b2c3d4-0101-4000-8000-000000000004', NOW(), NOW()),
('5f1ad87e-96fa-4c91-9cbf-75e5a381ed41', 'Khảo sát chất lượng dịch vụ', 'Đánh giá chất lượng dịch vụ hỗ trợ và chăm sóc khách hàng của chúng tôi.', 'PUBLIC', 'a77a908f-7385-4eba-81dd-4fc96bc1d22d', NOW(), NOW()),
('d4c338dc-c17f-4909-823f-90242525df68', 'Phản hồi về sản phẩm', 'Thu thập phản hồi chi tiết của bạn về sản phẩm để chúng tôi cải tiến tốt hơn.', 'PUBLIC', 'df4c19c5-02c2-40ec-8d48-32d515484ab7', NOW(), NOW());
